```js
const express = require("express");
const Redis = require("ioredis");
const DeepL = require("deepl");

const app = express();
app.use(express.json());

const redis = new Redis({
  host: process.env.REDIS_HOST || "localhost",
  port: Number(process.env.REDIS_PORT || 6379),
});

const translator = new DeepL.Translator(process.env.DEEPL_AUTH_KEY);
const inFlight = new Map();

app.post("/translate", async (req, res) => {
  const { text, targetLang } = req.body ?? {};

  if (typeof text !== "string" || !text.trim() ||
      typeof targetLang !== "string" || !targetLang.trim()) {
    return res.status(400).json({ error: "text and targetLang are required" });
  }

  // Include both inputs so different languages or texts never collide.
  const cacheKey = `translation:${targetLang}:${text}`;

  try {
    try {
      const cached = await redis.get(cacheKey);
      if (cached !== null) {
        return res.json({ translatedText: cached, cache: "hit" });
      }
    } catch (err) {
      console.warn("Redis read failed; translating directly:", err.message);
    }

    // Deduplicate simultaneous requests for the same translation.
    let work = inFlight.get(cacheKey);
    if (!work) {
      work = translator
        .translateText(text, null, targetLang)
        .then(async result => {
          const translatedText = result.text;
          try {
            await redis.set(cacheKey, translatedText, "EX", 900); // 15-minute TTL
          } catch (err) {
            console.warn("Redis write failed:", err.message);
          }
          return translatedText;
        })
        .finally(() => inFlight.delete(cacheKey));

      inFlight.set(cacheKey, work);
    }

    const translatedText = await work;
    return res.json({ translatedText, cache: "miss" });
  } catch (err) {
    console.error("Translation failed:", err);
    return res.status(502).json({ error: "Translation service unavailable" });
  }
});

app.listen(4500);
```

