Keep logging work off the game-loop thread: have the loop enqueue a small, already-formed event, and let a background worker batch and send events to Kafka.

```js
import { Kafka } from 'kafkajs';

const kafka = new Kafka({
  clientId: 'game-client',
  brokers: ['localhost:9092'],
});
const producer = kafka.producer();

const queue = [];
const MAX_QUEUE = 10_000;
let running = true;

export function logGameEvent(event) {
  // Keep this path fast: no network or disk I/O here.
  if (queue.length >= MAX_QUEUE) {
    // Choose and monitor an explicit overflow policy.
    return false;
  }
  queue.push({ ...event, timestamp: Date.now() });
  return true;
}

async function worker() {
  await producer.connect();

  while (running || queue.length) {
    if (queue.length === 0) {
      await new Promise(resolve => setTimeout(resolve, 10));
      continue;
    }

    const batch = queue.splice(0, 500);
    try {
      await producer.send({
        topic: 'cheat_events',
        messages: batch.map(value => ({ value: JSON.stringify(value) })),
      });
    } catch (err) {
      // Retry transient failures; after bounded retries, route failed events
      // to a dead-letter topic such as cheat_events_dlq.
      console.error('Failed to send event batch', err);
    }
  }
}
```

